steps.script:
for s in StratagemManager.get_implemented_faction_stratagems_for_player(2):
	if str(s.get("id", "")) == "faction_ork_kult_of_speed_speediest_freeks":
		return true
return false

var ms = GameState.get_unit("U_WARBIKERS_A").models
for i in range(ms.size()):
	ms[i]["position"] = {"x": 42.0 * 40.0, "y": (34.0 + 3.2 * i) * 40.0}
var ph = PhaseManager.get_current_phase_instance()
ph.game_state_snapshot = GameState.create_snapshot()
ph._compute_engagement_flags()
tree.root.get_node("Main")._recreate_unit_visuals()
return RulesEngine.is_unit_engaged("U_WARBIKERS_A", GameState.state)

for b in PhaseManager.get_current_phase_instance().dice_log:
	if str(b.get("context", "")) == "to_hit" and str(b.get("target_unit_id", "")) == "U_WARBIKERS_A":
		var rolls: Array = b.get("rolls_modified", b.get("rolls_raw", []))
		var four_plus := 0
		var two_three := 0
		for r in rolls:
			if int(r) >= 4:
				four_plus += 1
			elif int(r) >= 2:
				two_three += 1
		return int(b.get("successes", -1)) == four_plus and two_three > 0
return false

var found := false
var q: Array = [tree.root]
while not q.is_empty():
	var c = q.pop_front()
	if (c is Label or c is Button or c is RichTextLabel) and c.is_visible_in_tree() and str(c.text).to_upper().contains("SENTINEL STORM"):
		found = true
		break
	q.append_array(c.get_children())
return found
